import java.text.Normalizer

String base = basic.stringify(displayName)?.trim() ?: basic.stringify(name)?.trim()
if (!base) {
    return null
}
// strip diacritics only (basic.norm would also drop the dashes)
String ascii = Normalizer.normalize(base, Normalizer.Form.NFD).replaceAll('\\p{M}', '')
String nick = ascii.replaceAll('[^A-Za-z0-9._-]+', '-').replaceAll('^[-.]+|[-.]+$', '')
if (nick.length() > 64) {
    nick = nick.substring(0, 64)
}
return nick ?: null

import com.evolveum.midpoint.xml.ns._public.common.common_3.OrgType

String APP_ARCHETYPE = '2b89648a-2925-45ee-8cfd-d9965e050d1c'

String orgOid = assignment?.targetRef?.oid
if (!orgOid || assignment?.targetRef?.type?.localPart != 'OrgType') {
    return null
}
OrgType org = midpoint.getObject(OrgType.class, orgOid)
if (!org?.archetypeRef?.any { it?.oid == APP_ARCHETYPE }) {
    return null
}
return basic.stringify(org?.identifier)?.trim() ?: null
